 List<AccessController.Entry> Controls=>(List<AccessController.Entry>)Get(a,"controls");
 AccessController.Entry Focused {get{int i=(int)Get(a,"focused");return i>=0&&i<Controls.Count?Controls[i]:null;}}
 bool VisibleFocus(){var f=(RectTransform)Get(a,"focusRect");return f!=null&&f.gameObject.activeInHierarchy&&f.GetComponentsInParent<CanvasGroup>().All(x=>x.alpha>.01f);}
 IEnumerator Seek(string part){yield return Settle();sought=false;int count=Controls.Count+2;for(int i=0;i<count;i++){if(Focused!=null&&Focused.text.Split('.')[0].IndexOf(part,StringComparison.OrdinalIgnoreCase)>=0){sought=true;break;}yield return Keypress(Key.Tab);}Check(sought,"keyboard reaches "+part);if(sought)Check(VisibleFocus(),"visible focus: "+part);else File.WriteAllLines(dir+"/missing-"+log.Count+".txt",Controls.Select(x=>x.text));}
