 string State(){if(!g.HasSession)return "NO SESSION";var s=g.CaptureSave();s.utcTicks=1;return JsonUtility.ToJson(s);}
 IEnumerator Office(){a.ClosePanels();m.Resume();g.StartFromMenu();Call("ShowOffice");yield return Settle();}
 IEnumerator ShiftTab(){InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.LeftShift,Key.Tab));yield return Frames();InputSystem.QueueStateEvent(keyboard,new KeyboardState());yield return Settle();}
 void SetFocus(int i)=>typeof(AccessController).GetField("focused",F).SetValue(a,i);
 IEnumerator ArrowTo(string part){
  yield return Settle();if(Focused==null)yield return Keypress(Key.DownArrow);
  int initial=(int)Get(a,"focused"),n=Controls.Count;var edges=new int[n,4];var dirs=new[]{Vector2.up,Vector2.down,Vector2.left,Vector2.right};var keys=new[]{Key.UpArrow,Key.DownArrow,Key.LeftArrow,Key.RightArrow};
  // API exploration is setup only; the final route is executed by virtual Keyboard events.
  var scrolls=g.GetComponentsInChildren<ScrollRect>();var positions=scrolls.Select(x=>x.content.anchoredPosition).ToArray();
  for(int i=0;i<n;i++)for(int k=0;k<4;k++){SetFocus(i);if(k>=2&&Controls[i].target!=null&&Controls[i].target.GetComponentInChildren<Slider>()!=null){edges[i,k]=i;continue;}a.NavigateDirection(dirs[k]);edges[i,k]=(int)Get(a,"focused");for(int z=0;z<scrolls.Length;z++)scrolls[z].content.anchoredPosition=positions[z];Canvas.ForceUpdateCanvases();}
  SetFocus(initial);int goal=Controls.FindIndex(x=>x.text.Split('.')[0].IndexOf(part,StringComparison.OrdinalIgnoreCase)>=0);var queue=new Queue<int>();var paths=new Dictionary<int,List<int>>();if(initial>=0){queue.Enqueue(initial);paths[initial]=new List<int>();}
  while(queue.Count>0&&!paths.ContainsKey(goal)){int node=queue.Dequeue();for(int k=0;k<4;k++){int j=edges[node,k];if(j<0||j>=n||paths.ContainsKey(j))continue;paths[j]=new List<int>(paths[node]){k};queue.Enqueue(j);}}
  bool reachable=goal>=0&&paths.ContainsKey(goal);Check(reachable,"arrow route exists: "+part);
  if(reachable){foreach(int k in paths[goal])yield return Keypress(keys[k]);Check(Focused!=null&&Focused.text.Split('.')[0].IndexOf(part,StringComparison.OrdinalIgnoreCase)>=0,"virtual arrows reach: "+part);Check(VisibleFocus(),"arrow focus visible: "+part);}else {File.WriteAllLines(dir+"/unreachable-"+log.Count+".txt",Controls.Select(x=>x.text));yield return Seek(part);}
 }
 IEnumerator ArrowActivate(string label,Key key=Key.Enter){yield return ArrowTo(label);if(Focused!=null&&Focused.text.Split('.')[0].IndexOf(label,StringComparison.OrdinalIgnoreCase)>=0){yield return Keypress(key);yield return Settle();}}
