 public static string Effective(){var p=AccessPreferences.Current;var fields=typeof(AccessPreferences).GetFields(BindingFlags.Public|BindingFlags.Instance).Where(f=>!f.Name.StartsWith("profile")&&f.Name!="individualSchema"&&f.Name!="navigationSchema"&&f.Name!="keyboardChoiceSchema").OrderBy(f=>f.Name);return string.Join("|",fields.Select(f=>f.Name+"="+f.GetValue(p)))+"|desk="+JsonUtility.ToJson(DeskPreferences.Current);}
 void Migration(){
  string parent=DeskPreferences.TestDirectory;var records=new List<string>();
  for(int c=0;c<10;c++){
   string d=Path.Combine(parent,"migration-"+c);DeskPreferences.TestDirectory=DeskSaveStore.TestDirectory=d;DeskPreferences.Load();AccessPreferences.Load();var p=AccessPreferences.Current;p.keyboard=true;p.narrationVolume=.31f;p.interfaceScale=1.1f;p.navigationSchema=1;
   if(c>=1&&c<=4)p.ToggleProfile(c-1,true);
   if(c==5||c==6){p.ToggleProfile(0,true);p.ToggleProfile(1,true);p.ToggleProfile(2,true);}
   if(c==6){p.largeTargets=false;p.textScale=1.75f;DeskPreferences.Current.highContrast=false;p.CaptureManualProfileChanges();}
   if(c==7){p.profileSchema=0;p.profileMask=15;p.profileBase=null;p.profileApplied=null;p.textScale=1.25f;p.simpleDocuments=true;p.profileSnapshot="legacy snapshot must not reset effective values";}
