   if(c==9){p.navigationSchema=0;p.profileBase=new float[11];p.profileApplied=null;p.symbols=true;p.glossary=false;}
   string expected=Effective();if(c==9)expected=expected.Replace("glossary=False","glossary=True");Directory.CreateDirectory(d);File.WriteAllText(AccessPreferences.FilePath,JsonUtility.ToJson(p,true));DeskPreferences.Current.Save();File.Copy(AccessPreferences.FilePath,Path.Combine(d,"legacy.json"));
   DeskPreferences.Load();AccessPreferences.Load();Check(Effective()==expected,"migration preserves every effective field: case "+c);Check(P.profileMask==0&&P.profileBase==null&&P.profileApplied==null&&P.individualSchema==1,"migration removes all live layers: case "+c);
   P.simpleDocuments=!P.simpleDocuments;P.largeTargets=!P.largeTargets;P.textScale=1;P.Save();DeskPreferences.Current.Save();string edited=Effective();AccessPreferences.Load();Check(Effective()==edited&&P.profileMask==0,"individual edit survives reload without reapplication: case "+c);File.WriteAllText(Path.Combine(d,"expected.txt"),edited);records.Add(d);
  }
